//! pi-tui helpers for Rust extensions.
//!
//! The pure functions and values a Pi extension imports from `@earendil-works/pi-tui` to draw its own components: ANSI-aware width,
//! wrap, truncate and slice; key matching; fuzzy matching; colors; terminal capabilities. Every function follows Pi's own
//! implementation at the pinned release, and `test/parity/sdk-bulk` (generated by running Pi's functions) holds them to it byte for
//! byte. Names are Pi's in snake case (`visibleWidth` is [`visible_width`]).

mod colors;
mod fuzzy;
mod host;
mod keybindings;
mod keys;
mod lower;
mod tables;
mod terminal;
mod tui_keybindings;
mod text;
#[cfg(test)]
mod tests;

